import {Button} from '@primer/react'
import {Dialog} from '@primer/react/deprecated'
import styles from './RollbackCuratedImageVersionDialog.module.css'
import type {ImageDefinition, ImageVersion} from '../types/types'
import {rollbackCuratedImageToVersion} from '../services/curated-images'
import {FlashBanner, useFlashBannerState} from './FlashBanner'
import {curatedImageDetailsUrl} from '../helpers/urls'

interface RollbackCuratedImageVersionDialogProps {
  closeDialog: () => void
  curatedImageVersion: ImageVersion
  curatedImage: ImageDefinition
}

export function RollbackCuratedImageVersionDialog(props: RollbackCuratedImageVersionDialogProps) {
  const flashBanner = useFlashBannerState()

  const handleSubmit = async () => {
    flashBanner.hide()

    const response = await rollbackCuratedImageToVersion({
      id: props.curatedImageVersion.imageDefinitionId,
      version: props.curatedImageVersion.version,
    })
    if (response.ok) {
      flashBanner.showInfo(`Image rolled back to version ${props.curatedImageVersion.version}`)
      window.location.assign(curatedImageDetailsUrl(props.curatedImageVersion.imageDefinitionId))
    } else {
      flashBanner.showError(response.error)
    }
  }

  return (
    <Dialog isOpen onDismiss={() => props.closeDialog()}>
      <Dialog.Header>Rollback curated image to version</Dialog.Header>
      <div className={styles.dialogBody}>
        <FlashBanner state={flashBanner.state} />
        <p>
          Image: <strong>{props.curatedImage.name}</strong> (ID: {props.curatedImage.id})
        </p>
        <p>
          Are you sure that you want to rollback the curated image to version{' '}
          <strong>{props.curatedImageVersion.version}</strong>?
        </p>
        <Button variant="danger" onClick={handleSubmit}>
          Rollback
        </Button>
      </div>
    </Dialog>
  )
}
